using Netstorm.Client.Display;

namespace Netstorm.Tests;

/// <summary>
/// 명암 변환표의 보호 계약을 확인한다. 세 경우의 기대값은 cpppj/src/client/PaletteShade.cpp 와 같은 알고리즘을
/// 그대로 옮긴 별도 Python 참조 구현(shade_ref.py, 저장소에 두지 않음)으로 계산한 값이며 C# 결과로 바꾸지 않는다.
/// 원본 기계어 대조 fixture는 없으므로 L1이 아니라 계약 검사다. Gump 그리기 L1(R3)에서 끝까지 대조한다.
/// 근거: cpppj/src/client/PaletteShade.cpp. (R2a, 2026-10-28)
/// </summary>
public sealed class ShadeMapsTests
{
    /// <summary>무작위 논리 팔레트 세 경우의 명암 표가 참조 구현과 같다.</summary>
    [Fact]
    public void RandomPalettesMatchReferenceImplementation()
    {
        (string logical, string bright, string dark)[] cases = [(Logical0, Bright0, Dark0), (Logical1, Bright1, Dark1), (Logical2, Bright2, Dark2)];
        // 경우마다 논리 팔레트를 복원해 같은 입력으로 표를 만든다
        foreach ((string logical, string bright, string dark) in cases)
        {
            uint[] words = logical.Split(',').Select(piece => Convert.ToUInt32(piece, 16)).ToArray();
            Assert.Equal(256, words.Length);
            GumpShadeMaps maps = PaletteShade.BuildGumpShadeMaps(words);
            Assert.Equal(bright.Split(',').Select(byte.Parse), maps.Bright);
            Assert.Equal(dark.Split(',').Select(byte.Parse), maps.Dark);
        }
    }

    /// <summary>회색 팔레트의 자명한 경우를 고정한다. 밝힘·어둡힘의 반올림 경계는 참조 구현 경우에 맡긴다.</summary>
    [Fact]
    public void GrayPaletteMapsToNearestGray()
    {
        var logical = new uint[256];
        // 각 번호를 같은 값의 회색으로 채운다
        for (int i = 0; i < 256; i++) logical[i] = (uint)(i | (i << 8) | (i << 16));
        GumpShadeMaps maps = PaletteShade.BuildGumpShadeMaps(logical);
        Assert.Equal(0, maps.Bright[0]);
        Assert.Equal(150, maps.Bright[100]);
        Assert.Equal(255, maps.Bright[200]);
        Assert.Equal(0, maps.Dark[0]);
        Assert.Equal(60, maps.Dark[100]);
        Assert.Equal(153, maps.Dark[255]);
    }

